-- Migration v6.3 — generation years corrected against published sources
--
-- Every generation row was checked on 2026-11-14 against the manufacturer's press
-- pages or the model's Wikipedia article (the page read is in source_url).
-- Conventions, unchanged: calendar years of sale in Europe; two generations of
-- a model never share a year, the changeover year belonging to the new one.
--
--   386 rows checked: 41 corrected, the rest confirmed
--   78 generations added (mostly 2002-2012 predecessors: a 2008 car of
--       these models found no generation at all)
--   2 rows removed
--   2 rows the check could not settle are left as they were, unverified
--
-- The commonest error: a generation left open ("still on sale") after the car
-- was withdrawn, and launch years of another market (China, Russia) in place
-- of Europe's.
--
-- Rows are found by brand, model and generation name. Idempotent.

BEGIN;

ALTER TABLE generations
    ADD COLUMN IF NOT EXISTS source_url  TEXT,
    ADD COLUMN IF NOT EXISTS verified_on DATE;

-- ── removed ──────────────────────────────────────────────────────────────────

-- Cupra Leon before 2020: that car is a SEAT León Cupra, no Cupra-brand León existed
WITH gone AS (
    SELECT g.id FROM generations g JOIN vehicle_models vm ON vm.id = g.model_id JOIN brands b ON b.id = vm.brand_id
    WHERE b.name = 'Cupra' AND vm.name = 'Leon' AND g.name = 'Leon I'
), a AS (UPDATE price_observations SET generation_id = NULL WHERE generation_id IN (SELECT id FROM gone)),
   b AS (DELETE FROM reliability_evidence WHERE generation_id IN (SELECT id FROM gone)),
   c AS (DELETE FROM reliability_scores_history WHERE generation_id IN (SELECT id FROM gone)),
   d AS (DELETE FROM market_price_stats_history WHERE generation_id IN (SELECT id FROM gone))
DELETE FROM generations WHERE id IN (SELECT id FROM gone);

-- Lexus IS 2020 facelift: never sold in Europe
WITH gone AS (
    SELECT g.id FROM generations g JOIN vehicle_models vm ON vm.id = g.model_id JOIN brands b ON b.id = vm.brand_id
    WHERE b.name = 'Lexus' AND vm.name = 'IS' AND g.name = 'IS III 2nd facelift'
), a AS (UPDATE price_observations SET generation_id = NULL WHERE generation_id IN (SELECT id FROM gone)),
   b AS (DELETE FROM reliability_evidence WHERE generation_id IN (SELECT id FROM gone)),
   c AS (DELETE FROM reliability_scores_history WHERE generation_id IN (SELECT id FROM gone)),
   d AS (DELETE FROM market_price_stats_history WHERE generation_id IN (SELECT id FROM gone))
DELETE FROM generations WHERE id IN (SELECT id FROM gone);

-- ── corrected and confirmed ──────────────────────────────────────────────────
-- new_name / new_start NULL = unchanged; set_end says whether year_end changes.
UPDATE generations g
SET name        = COALESCE(v.new_name, g.name),
    year_start  = COALESCE(v.new_start, g.year_start),
    year_end    = CASE WHEN v.set_end THEN v.new_end ELSE g.year_end END,
    source_url  = v.source_url,
    verified_on = DATE '2026-11-14'
FROM (VALUES
