    ('Volkswagen', 'Polo', 'Polo IV (9N/9N3)', 2001::int, 2008::int, NULL::text, 'https://en.wikipedia.org/wiki/Volkswagen_Polo'::text),
    ('Volkswagen', 'Sharan', 'Sharan I (7M)', 1995::int, 2009::int, NULL::text, 'https://en.wikipedia.org/wiki/Volkswagen_Sharan'::text),
