) AS v(brand, model, name, year_start, year_end, fuel_type, source_url)
JOIN brands b ON b.name = v.brand
JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE NOT EXISTS (SELECT 1 FROM generations g WHERE g.model_id = vm.id AND g.name = v.name);

-- ── year ends set by hand ────────────────────────────────────────────────────
-- The old generation keeps the changeover year when its successor arrives in
-- the last months of it, and covers a year or two in which the model had no
-- successor yet (cars registered then are old stock).
UPDATE generations g
SET year_end = v.year_end
FROM (VALUES
    ('Audi', 'Q7', 'Q7 4M', 2026),  -- G8 on the market from September 2026
    ('BMW', 'X5', 'X5 G05', 2026),  -- G65 on the market in autumn 2026
    ('Mercedes-Benz', 'GLA', 'GLA H247', 2026),  -- successor on the market in November 2026
    ('DS', '7', 'DS 7 I', 2025),  -- DS N°7 on sale from 2026
    ('BMW', 'Z4', 'Z4 E89', 2017),  -- no Z4 was built between August 2016 and 2018
    ('Citroën', 'C4', 'C4 II', 2019),  -- no C4 between the II and the III of 2020
    ('DS', '4', 'DS 4 I', 2020),  -- no DS 4 between 2018 and the II of 2021
    ('Nissan', 'Micra', 'Micra K14', 2025),  -- no Micra between 2023 and the electric one of 2026
    ('Renault', 'Twingo', 'Twingo III', 2025),  -- no Twingo between June 2024 and the electric one of 2026
    ('Subaru', 'BRZ', 'BRZ I', 2022)   -- no BRZ in Europe between the two generations
) AS v(brand, model, name, year_end)
JOIN brands b ON b.name = v.brand
JOIN vehicle_models vm ON vm.brand_id = b.id AND vm.name = v.model
WHERE g.model_id = vm.id AND g.name = v.name;

COMMIT;
